ValidationRule.errorConditionFormula:
OR( 
/* fire for new appeals created in a stage other than 'Acknowledge Receipt' */ 
AND( 
ISNEW(), 
NOT(ISPICKVAL(Appeal_Stage__c, "Acknowledge Receipt")) 
) , 

/* fire for open appeals edited by someone not enabled to do so */ 
AND( 
NOT(ISNEW()), 
ISCHANGED(Appeal_Stage__c),
NOT(ISPICKVAL(PRIORVALUE(Appeal_Stage__c), "Denied")), 
$Profile.Name <> "IM_Commissions",
$Profile.Name <> "IM_Sales Ops" , 
$Profile.Name <> "IM_Sales Ops Super User" , 
$Profile.Name <> "IM_Sales_Ops-Cleanup Temporary" ,  
$Profile.Name <> "IM_Custom Sys Admin" 
) , 

/* fire on resubmits when resubmit stage != resubmitted */ 
AND( 
ISPICKVAL(PRIORVALUE(Appeal_Stage__c), "Denied" ), 
NOT(ISPICKVAL(Appeal_Stage__c, "Resubmitted")) 
) 
)
